Ltac c1fin HR'0 Hms0 Hlf0 KC R1 G11tac :=
  let J2 := fresh "J2" in let J8 := fresh "J8" in let J9 := fresh "J9" in let J10 := fresh "J10" in
  let J19 := fresh "J19" in let J21 := fresh "J21" in let J23 := fresh "J23" in let J11 := fresh "J11" in
  let GKx := fresh "GKx" in
  rreg HR'0 2%bv J2; rreg HR'0 8%bv J8; rreg HR'0 9%bv J9; rreg HR'0 10%bv J10; rreg HR'0 19%bv J19;
  rreg HR'0 21%bv J21; rreg HR'0 23%bv J23; rreg HR'0 11%bv J11;
  lazymatch type of HR'0 with regs_ok _ _ ?RR =>
    assert (GKx : forall r, In r [3; 4; 26; 27]%bv -> getr RR r = getr R1 r) by
      (intros r Hr; eapply (syms_id_sound R1 _ _ _ [3; 4; 26; 27]%bv HR'0); [vm_cast_no_check (@eq_refl bool true) | exact Hr]) end;
  eapply KC; [exact Hms0 | exact Hlf0 | exact J2 | rewrite GKx by inb; reflexivity | rewrite GKx by inb; reflexivity
             | exact J8 | exact J9 | exact J10 | rewrite J11; G11tac | exact J19 | exact J21 | exact J23
             | rewrite GKx by inb; reflexivity | rewrite GKx by inb; reflexivity].

