Lemma dsh_inapp : forall lo hi a b A n, in_app_mem lo hi -> lo <= a -> b <= hi -> 0 <= A -> 0 <= n -> A + n <= 2 ^ 47 ->
  disjoint_from [(a, b)] (sh A) (nsh n).
Proof.
  intros lo hi a b A n Hm Ha Hb HA Hn HAn. cbn [disjoint_from]. split; [|exact I].
  pose proof (sh_nsh_high A n HA Hn ltac:(unfold AAPP_HI; lia)) as Hs.
  assert (ASHADOW_BASE <= sh A) by (unfold sh; pose proof (Z.div_pos A 8 HA ltac:(lia)); lia).
  unfold in_app_mem in Hm. lia.
Qed.

Lemma perm_inc3 : forall (LB LBa LBx LBb : list block), Permutation LB (LBa ++ LBx ++ LBb) ->
  forall b, In b (LBa ++ LBb) -> In b LB.
Proof.
  intros LB LBa LBx LBb P b Hb. apply (Permutation_in _ (Permutation_sym P)).
  apply in_app_or in Hb. destruct Hb as [Hb|Hb]; apply in_or_app; [left; exact Hb | right; apply in_or_app; right; exact Hb].
Qed.

Lemma perm_in_mid : forall (LB LBa LBb : list block) b, Permutation LB (LBa ++ [b] ++ LBb) -> In b LB.
Proof.
  intros LB LBa LBb b P. apply (Permutation_in _ (Permutation_sym P)). apply in_or_app. right. left. reflexivity.
Qed.

Lemma hdr40_transport : forall W m m' o bl bc fst sz mlf pad, hdr40 m o bl bc fst sz mlf pad -> munch W m m' -> wmono asegs m m' ->
  disjoint_from W o 40 -> hdr40 m' o bl bc fst sz mlf pad.
Proof. intros W m m' o bl bc fst sz mlf pad Hh MU WM DJ. unfold hdr40 in *. exact (rw_cells_transport _ _ _ _ _ _ Hh MU WM DJ). Qed.
