  Definition wT (iv : Z * Z) : Prop :=
    (o1 <= fst iv /\ snd iv <= o1 + 40) \/ (o2 <= fst iv /\ snd iv <= o2 + 40) \/ (lo <= fst iv /\ snd iv <= spz - 96).

  Lemma u_bnds : forall LBs2 bl2 bc2 ents2, umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    (bc2 <> 0 -> bl2 + 8 * bc2 <= 2 ^ 47) /\ (forall p k v, In (p, (k, v)) ents2 -> p + 24 <= 2 ^ 47) /\
    (bc2 <> 0 -> 0 <= bl2) /\ (forall p k v, In (p, (k, v)) ents2 -> 0 <= p) /\ 0 <= bc2.
  Proof.
    intros LBs2 bl2 bc2 ents2 U.
    split; [intros _; exact (u_bl_hi U)|].
    split; [intros p k v Hi; destruct (u_node U p k v Hi) as (_ & _ & Hp & _); exact Hp|].
    split; [intros Hbc; pose proof (u_bl_lo U Hbc); lia|].
    split; [intros p k v Hi; destruct (u_node U p k v Hi) as (_ & Hp & _); lia|].
    pose proof (BSEQ_boundT bc2 (u_bseq U)); lia.
  Qed.

  Lemma dsh_xob : forall A n, 0 <= A -> 0 <= n -> A + n <= 2 ^ 47 -> disjoint_from XOB (sh A) (nsh n).
  Proof.
    intros A n HA Hn HAn. destruct O1R as (_ & _ & _ & M1o). destruct O2R as (_ & _ & _ & M2o & _).
    pose proof (dsh_inapp _ _ o1 (o1 + 40) A n M1o ltac:(lia) ltac:(lia) HA Hn HAn) as D1.
    pose proof (dsh_inapp _ _ o2 (o2 + 40) A n M2o ltac:(lia) ltac:(lia) HA Hn HAn) as D2.
    unfold XOB. cbn [disjoint_from] in *. tauto.
  Qed.
