  Lemma TS_hdr : forall s LB bl2 bc2 ents2 LBs2 m m',
    TS s LB bl2 bc2 ents2 LBs2 m -> munch XOB m m' -> wmono asegs m m' -> mem_inv asegs m' ->
    (forall b, In b (LB0 ++ LBs2) -> In b LB) ->
    (bc2 <> 0 -> bl2 + 8 * bc2 <= 2 ^ 47) -> (forall p k v, In (p, (k, v)) ents2 -> p + 24 <= 2 ^ 47) ->
    (bc2 <> 0 -> 0 <= bl2) -> (forall p k v, In (p, (k, v)) ents2 -> 0 <= p) -> 0 <= bc2 ->
