  Definition mva_post (bl2 bc2 : Z) (ents2 : list (Z * (Z * Z))) (LBs2 : list block) : config -> Prop :=
    fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H) (LB' : list block) (F' : bvmap 5 word),
      as_VIS H s' (cfg_ms cf) = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                                   F' (ret_pc ra) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' cf /\ as_MPRES H mo0 (cfg_model cf)
      /\ mem_inv asegs m' /\ stk asegs m' lo spz /\ rw_cells asegs m' (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m' B
      /\ as_RHEAP H s' LB' m' /\ Permutation LB' (LB0 ++ LBs2)
      /\ umapx MI_A 24 (nval24 ASEGS) (lbl LB') m' o1 bl2 bc2 ents2 /\ umap_sh m' 24 (bl2, bc2, ents2)
      /\ umapx MI_A 24 (nval24 ASEGS) (lbl LB') m' o2 0 0 []
      /\ addressable m' o1 40 /\ addressable m' o2 40
      /\ xpres H LB0 spz [(o1, o1 + 40); (o2, o2 + 40)] m0 m'
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H st0
      /\ lb_own LB' m'.

