  Lemma mva_fin : forall (bl2 bc2 : Z) (ents2 : list (Z * (Z * Z))) (LB LBs2 : list block)
      (x1 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 x22 x23 x24 x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_END) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    mem_inv asegs m -> stk asegs m lo spz -> rw_cells asegs m (errno_addr tp) [C4 errv] -> as_rauxv_ok H m B ->
    ACONST m -> as_RFS H LF m -> stack0 m lo shi ->
    mva_frame m (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 ->
    as_RHEAP H s LB m -> Permutation LB (LB0 ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    hdr40 m o1 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0x3f800000) pad2 ->
    addressable m o1 40 -> addressable m o2 40 ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 -> Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall p k v, In (p, (k, v)) ents2 -> agree_on m0 m p 24) ->
    (forall i, 0 <= i < bc2 -> (ents2 = [] \/ i <> hmod (hdkey ents2) bc2) -> agree_on m0 m (bl2 + 8 * i) 8) ->
    (ents2 <> [] -> cell8 ASEGS m (bl2 + 8 * hmod (hdkey ents2) bc2) (o1 + 16)) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    umap_sh m 24 (bl2, bc2, ents2) ->
    xpres H LB0 spz [(o1, o1 + 40); (o2, o2 + 40)] m0 m ->
    lb_own LB m ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo).
