  assert (NAG : forall p' k' v', In (p', (k', v')) ((p, (k, v)) :: ents2') -> HRepFacts.agree_on m0 m2 p' 24).
  { intros p' k' v' Hin. destruct (NODEB p' k' v' Hin) as (q' & Hq').
    destruct (u_node U2 p' k' v' Hin) as (_ & Np0 & Np1 & _ & _ & _ & _ & _ & Npo & Npb).
    pose proof (Npb ltac:(lia)) as Npb'.
    assert (HqL' : In (q', p', 24) LB) by (apply (Permutation_in _ (Permutation_sym PE)); apply in_or_app; right; exact Hq').
    pose proof (ah_blocks H HH _ _ _ _ RH HqL') as (_ & _ & _ & _ & QC & _). cbn [blk_addr blk_size Datatypes.fst Datatypes.snd] in QC.
    pose proof (AP2 _ Hq') as Npo1. cbn [blk_addr blk_size Datatypes.fst Datatypes.snd] in Npo1.
    eapply HRepFacts.agree_on_trans.
    - eapply (agree_of_xpres H); [exact XP | | lia | lia]. intros i Hi. unfold xclient. split.
      + right; right; left. exists (q', p', 24).
        split; [apply in_or_app; right; exact Hq' | cbn [blk_addr blk_size Datatypes.fst Datatypes.snd]; lia].
      + unfold XOB. cbn [rin_ivs Datatypes.fst Datatypes.snd]. unfold apart in Npo, Npo1. lia.
    - apply (t2c_agree_munch _ _ _ _ _ MU); [| lia | lia]. cbn [disjoint_from]. unfold apart in Npb', Npo. unfold AINTRIN_STACK.
      repeat split; lia. }
  assert (BAG : forall i, 0 <= i < bc2 -> ((p, (k, v)) :: ents2' = [] \/ i <> hmod (hdkey ((p, (k, v)) :: ents2')) bc2) ->
                HRepFacts.agree_on m0 m2 (bl2 + 8 * i) 8).
  { intros i Hi Hne. destruct Hne as [Hne | Hne]; [discriminate Hne|]. cbn [hdkey] in Hne. fold ix in Hne.
    eapply HRepFacts.agree_on_trans; [eapply HRepFacts.agree_on_sub; [exact AGB | lia | lia]|].
    apply (t2c_agree_munch _ _ _ _ _ MU); [| lia | lia]. cbn [disjoint_from]. unfold apart in BLO. unfold AINTRIN_STACK.
    repeat split; lia. }
  assert (CS2 : rw_cells asegs m2 (bl2 + 8 * ix) [C8 (Z_to_bv 64 (o1 + 16))]).
  { eapply rw_cells_transport; [exact CS1 | exact MU2 | exact WM2 |].
    cbn [disjoint_from cells_size csize]. unfold apart in BLO. unfold AINTRIN_STACK. repeat split; lia. }
  assert (CL2 : HRep.cellw asegs m2 (bl2 + 8 * ix) 8 (o1 + 16)) by (apply cellw8_of_rw_cells; [exact CS2 | lia | lia]).
  assert (USH2 : umap_sh m2 24 (bl2, bc2, (p, (k, v)) :: ents2')).
  { unfold umap_sh. split.
    - intros _. cbn [HStmts.t3a HStmts.t3b Datatypes.fst Datatypes.snd].
      eapply addressable_transport; [exact (USB ltac:(lia)) | exact MU | exact WM | apply DSH; lia].
    - intros p' k' v' Hin. cbn [HStmts.t3c Datatypes.snd] in Hin. destruct (u_node U2 p' k' v' Hin) as (_ & Np0 & Np1 & _).
      eapply addressable_transport; [exact (USN p' k' v' Hin) | exact MU | exact WM | apply DSH; lia]. }
  assert (XP2 : xpres H LB0 spz XOB m0 m2).
  { eapply (xpres_munch_mixed H HH s LB LB0 LBs2 spz XOB _ m0 m3 m2); [ | exact RH | exact PE | lia | exact MU | exact WM | ].
    - eapply xpres_weaken; [exact XP | lia | intros b Hb; apply in_or_app; left; exact Hb | intros a Ha; exact Ha].
    - apply Forall_cons; [right; right; exists qb, bl2, (8 * bc2); split; [exact INQ | cbn [Datatypes.fst Datatypes.snd]; lia]|].
      apply Forall_cons; [right; left; intros a Ha; unfold XOB; cbn [rin_ivs Datatypes.fst Datatypes.snd] in *; lia|].
      apply Forall_cons; [left; cbn [Datatypes.fst Datatypes.snd]; unfold AINTRIN_STACK; lia | apply Forall_nil]. }
  assert (FR2 : mva_frame m2 (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9).
  { unfold mva_frame in FR |- *. eapply rw_cells_transport; [exact FR | exact MU | exact WM |].
    cbn [disjoint_from cells_size csize]. unfold AINTRIN_STACK. repeat split; lia. }
  assert (ERR2 : rw_cells asegs m2 (errno_addr tp) [C4 errv]).
  { eapply rw_cells_transport; [exact ERR | exact MU | exact WM |]. rewrite TPV, u64_of_Z by (unfold ATP; lia).
    cbn [disjoint_from cells_size csize]. unfold ATP, AINTRIN_STACK in *. unfold AIMG_TOP in HqI. repeat split; lia. }
  assert (ST2' : stk asegs m2 lo spz).
  { eapply stk_merge; [exact ST2 | | lia].
    eapply stk_transport_disjoint; [exact (proj2 (stk_split asegs M1 lo (spz - 96) spz ST1 ltac:(lia))) | exact MU2 | exact WM2 |].
    cbn [disjoint_from]. unfold AINTRIN_STACK. repeat split; lia. }
  assert (OWN2 : lb_own LB m2) by exact (lb_own_wmono _ _ _ OWN WM).
  eapply mva_fin with (s := s) (msF := msF2) (mo := mo2) (m := m2) (pad1 := pad1) (pad2 := pad2).
  - exact VIS2.
  - exact KR2.
  - eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]].
  - exact MI2.
  - exact ST2'.
  - exact ERR2.
  - exact RA2.
  - exact AC2.
  - exact RF2.
  - exact S02.
  - exact FR2.
  - exact RH2.
  - exact PE.
  - exact AL.
  - exact HD1m.
  - exact HD2m.
  - exact AD1m.
  - exact AD2m.
  - exact U2.
  - exact PM2.
  - exact NAG.
  - exact BAG.
  - intros _. exact CL2.
  - exact AP2.
  - exact USH2.
  - exact XP2.
  - exact OWN2.
Qed.

  Set Ltac Profiling.
