  Lemma t2_agree : forall s LB bl2 bc2 ents2 LBs2 M A n,
    TS s LB bl2 bc2 ents2 LBs2 M -> (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    In (A, n) (lbl LBs2) -> apart A n o2 40 -> 0 <= A -> A + n <= 2 ^ 64 -> HRepFacts.agree_on m0 M A n.
  Proof.
    intros s LB bl2 bc2 ents2 LBs2 M A n HT AP2 HIn HA2 HA0 HAn.
    destruct HT as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & XP & _).
    apply in_map_iff in HIn. destruct HIn as [[[q A'] n'] [Heq Hb]]. cbn in Heq. inversion Heq; subst A' n'.
    pose proof (AP2 _ Hb) as Ho1. unfold blk_addr, blk_size in Ho1; cbn in Ho1.
    eapply agree_of_xpres; [exact XP | | lia | lia].
    intros i Hi. split.
    - eapply (aclient_range_addr _ _ _ A n); [eapply (aclient_range_block _ _ _ q A n A n); [apply in_or_app; right; exact Hb | lia | lia] | lia].
    - unfold XOB. cbn [rin_ivs fst snd]. unfold apart in Ho1, HA2. lia.
  Qed.

  Ltac t2_fd := lazymatch goal with |- ?l = _ => let v := eval vm_compute in l in exact (@eq_refl _ v <: l = v) end.
  Lemma mva_t2 : forall (bl2 bc1 bc2 : Z) (ents2 : list (Z * (Z * Z))) (LB LBs2 : list block)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) x10 x11 x12 x13 x14 x15 x16 x17
                             (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 2147450880) (rSh (rO o1 24)) (rSh (Z_to_bv 64 o1))
                             x24 x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_T2) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TS s LB bl2 bc2 ents2 LBs2 m ->
    Permutation LB (LB0 ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    hdr40 m o1 (Z_to_bv 64 bl2) (Z_to_bv 64 bc1) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 0) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad2 ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo).
Proof.
  intros bl2 bc1 bc2 ents2 LB LBs2 x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31
    F msF mo m s pad1 pad2 VIS KR MP HTS PE AL HD1 HD2 U2 PM2 AP2.
  pose proof HTS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  unfold AIMG_TOP in O1a, O2a. unfold in_app_mem, ASHADOW_BASE, AHI_LO, AAPP_HI in O1d, O2d.
  pose proof AP12 as AP12u. unfold apart in AP12u.
  destruct (u_bnds _ _ _ _ U2) as (UB1 & UB2 & UB3 & UB4 & UB5).
  pose proof (BSEQ_boundT bc2 (u_bseq U2)) as BCB.
  pose proof (u_load U2) as ULD.
  assert (ZL0 : 0 <= Zlength ents2) by (unfold Zlength; lia).
  assert (HP : 0 <= hdaddr ents2 < 2 ^ 47).
  { destruct ents2 as [|[p [k v]] ents2']; cbn [hdaddr]; [lia|].
    pose proof (UB2 p k v (or_introl eq_refl)). pose proof (UB4 p k v (or_introl eq_refl)). lia. }
  assert (GZ1 : gz m o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  assert (GZ2 : gz m o2 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD2 | change (8 * (40 / 8)) with 40; lia]).
  destruct (hdr40_split _ _ _ _ _ _ _ _ HD1) as (P0 & P8 & P16 & P24 & P32 & P36).
  destruct (hdr40_split _ _ _ _ _ _ _ _ HD2) as (Q0 & Q8 & Q16 & Q24 & Q32 & Q36).
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 (spz - 96); Z_to_bv 64 bc2; Z_to_bv 64 (Zlength ents2);
                      Z_to_bv 64 (hdaddr ents2)]).
  assert (HR : regs_ok E t2_srT2 R).
  { apply regs_ok_srs; [apply regs_ok_seed|].
    repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
  assert (HK : know_ok asegs E m (kn_fix 20 [MVA_FLW] (SCR [] [] []) MVA_T2 t2_srT2 KNT2 40)).
  { kn_eval. unfold know_ok.
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact O1c]|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact O2c]|].
    apply Forall_cons; [cbn [kentry_ok]; unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; unfold apart in AP12; lia|].
    apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ o1 40); [exact (proj2 HD1) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|].
    apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ o2 40); [exact (proj2 HD2) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ (o2 + 8) _ 0%nat); [exact Q8 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ (o2 + 16) _ 0%nat); [exact Q16 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs _ _ (o2 + 24) _ 0%nat); [exact Q24 | reflexivity | reflexivity | lia | rwc_norm | lia | cbn; lia | reflexivity]|].
    know_tac. }
  xrun_at (PropExec.mkFP F fc) asegs R MVA_T2 m (seg_rom asegs) HR HK 60%nat [MVA_FLW] (SCR [] [] []) 40%N.
  { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
  lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
  lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ ?pc ?mm _) =>
    change mm with (mem_denot E m LG) in Hms; change pc with (Z_to_bv 64 MVA_FLW) in Hms end.
  set (M1 := mem_denot E m LG) in Hms.
  lazymatch type of HD2 with hdr40 _ _ _ _ _ _ (Z_to_bv 64 ?z) _ => set (mlfz := z) in HD1, HD2, P32, Q32 end.
  assert (MLFR : 0 <= mlfz < 2 ^ 32) by (unfold mlfz; lia).
  set (LG2 := SE (SA (EVar 32) 32) 4 (ELit mlfz) :: LG).
  set (M2 := mem_denot E m LG2).
  assert (FL32 : flat E (SA (EVar 32) 32) (Z.of_nat 4)) by (unfold flat, estart; evs; rewrite u64_of_Z by lia; cbn [a_off Z.of_nat]; lia).
  assert (LF2 : log_flat E LG2) by (unfold LG2; cbn [log_flat]; split; [lia | split; [exact FL32 | exact Hlf]]).
  assert (MU2 : munch XOB m M2).
  { unfold M2. apply munch_mem_denot; [exact LF2|]. unfold XOB, LG2, LG.
    repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
    apply Forall_nil. }
  assert (WM2 : wmono asegs m M2) by (unfold M2; apply wmono_mem_denot).
  assert (Q32M : rw_cells asegs M1 (o2 + 32) [C4 (Z_to_bv 64 mlfz)]) by (unfold M1, LG; rwc_keep Q32 Hlf).
  assert (P32M : rw_cells asegs M1 (o1 + 32) [C4 (Z_to_bv 64 mlfz)]) by (unfold M1, LG; rwc_keep P32 Hlf).
  assert (HD1M : hdr40 M2 o1 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 0) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 mlfz) pad1).
  { apply hdr40_join.
    - unfold M2, LG2, LG; rwc_keep P0 LF2.
    - unfold M2, LG2, LG; rwc_new LF2 (proj2 P8).
    - unfold M2, LG2, LG; rwc_keep P16 LF2.
    - unfold M2, LG2, LG; rwc_new LF2 (proj2 P24).
    - unfold M2, LG2, LG; rwc_new LF2 (proj2 P32).
    - unfold M2, LG2, LG; rwc_keep P36 LF2. }
  assert (HD2M : hdr40 M2 o2 (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 mlfz) pad2).
  { apply hdr40_join.
    - unfold M2, LG2, LG; rwc_keep Q0 LF2.
    - unfold M2, LG2, LG; rwc_new LF2 (proj2 Q8).
    - unfold M2, LG2, LG; rwc_keep Q16 LF2.
    - unfold M2, LG2, LG; rwc_keep Q24 LF2.
    - unfold M2, LG2, LG; rwc_keep Q32 LF2.
    - unfold M2, LG2, LG; rwc_keep Q36 LF2. }
  assert (ADR : Z_to_bv 64 (o1 + 32) = adenot E (SA (EVar 32) 32)) by (unfold adenot; evs; rewrite v_addi_Z by lia; reflexivity).
  assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
  readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
  rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10. rreg HR' 11%bv G11. rreg HR' 12%bv G12.
  rreg HR' 13%bv G13. rreg HR' 14%bv G14. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
  rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23.
  rewrite w_add in G10, G11 by lia.
  assert (RD : PropExec.rdn asegs M1 (Z_to_bv 64 (o2 + 32)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 mlfz)))
    by exact (proj2 (cellw4_of_rw_cells _ _ _ Q32M MLFR ltac:(lia))).
  assert (A10 : v_addi (getr R' 10) (bv_signed (0%bv : bv 12)) = Z_to_bv 64 (o2 + 32)).
  { rewrite G10. change (bv_signed (0%bv : bv 12)) with 0. rewrite v_addi_Z by lia. f_equal; lia. }
  pose proof (fp_step_flw (PropExec.mkFP F fc) asegs R' (Z_to_bv 64 MVA_FLW) M1 (seg_rom asegs) W_f51f4 15%bv 10%bv 0%bv
                (Z_to_bv 64 (o2 + 32)) _ F_f51f4 eq_refl D_f51f4 A10 RD) as S1.
  rewrite flw_nan_box in S1 by exact MLFR.
  cbn [PropExec.fp_regs PropExec.fp_csr] in S1.
  set (F1 := bvmap_set 15%bv (nan_box (Z_to_bv 32 mlfz)) F) in S1.
  rewrite v_addi_Z in S1 by (unfold MVA_FLW; lia).
  assert (S2 : RiscvSemantics.step asegs (@PropExec.mkst (PropExec.mkFP F1 fc) R' (Z_to_bv 64 (MVA_FLW + 4)) M1 (seg_rom asegs))
             = MachineOk (@PropExec.mkst (PropExec.mkFP F1 fc) R' (Z_to_bv 64 MVA_FSW) M1 (seg_rom asegs))).
  { erewrite step_bne_ft; [ | t2_fd | reflexivity | t2_fd |
      lazymatch goal with |- PropExec.c_eq (getr _ ?r1) (getr _ ?r2) = true =>
        replace r1 with (14%bv : reg) by (apply bv_eq; reflexivity); replace r2 with (0%bv : reg) by (apply bv_eq; reflexivity) end;
      unfold PropExec.c_eq; rewrite G14; reflexivity ].
    rewrite v_addi_Z by (unfold MVA_FLW; lia). reflexivity. }
  assert (A11 : v_addi (getr R' 11) (bv_signed (0%bv : bv 12)) = Z_to_bv 64 (o1 + 32)).
  { rewrite G11. change (bv_signed (0%bv : bv 12)) with 0. rewrite v_addi_Z by lia. f_equal; lia. }
  assert (SOK : RiscvSemantics.store_ok asegs M1 (Z_to_bv 64 (o1 + 32)) 4 = true).
  { pose proof (wr_at_store_ok asegs M1 (o1 + 32) 4 0 4 (proj2 P32M) ltac:(lia) ltac:(lia)) as X.
    rewrite Z.add_0_r in X. exact X. }
  pose proof (fp_step_fsw (PropExec.mkFP F1 fc) asegs R' (Z_to_bv 64 MVA_FSW) M1 (seg_rom asegs) W_f51fc 11%bv 15%bv 0%bv
                (Z_to_bv 64 (o1 + 32)) F_f51fc eq_refl D_f51fc A11 SOK) as S3.
  assert (FR15 : reg_get F1 15%bv = nan_box (Z_to_bv 32 mlfz)) by (unfold F1, reg_get; rewrite bvmap_get_set_same; reflexivity).
  cbn [PropExec.fp_regs] in S3. rewrite FR15, fsw_bytes in S3 by exact MLFR.
  rewrite v_addi_Z in S3 by (unfold MVA_FSW; lia).
  replace (MVA_FSW + 4) with MVA_T4 in S3 by (unfold MVA_FSW, MVA_T4; lia).
  rewrite ADR in S3.
  lazymatch type of S3 with _ = MachineOk (@PropExec.mkst _ _ _ ?mm _) => change mm with M2 in S3 end.
  assert (HmsT : CatSim.msteps asegs (MS R F (Z_to_bv 64 MVA_T2) fc None m (seg_rom asegs))
