      [ exact FR3 | exact VIS3 | exact KR3 | exact (ah_mpres_trans H HH _ _ _ MP01 MP3) | exact J2 | exact J3 | exact J4 | exact J8
      | exact J9 | exact J10 | exact J12 | exact J19 | exact J21 | exact J23 | exact J26 | exact J27 | exact TS3 | exact PE | exact AL
      | exact HD1F | exact HD2F | exact U2 | exact PM2 | exact AP2 ].
Qed.

  Lemma t1_kn_pre : forall (segs : list Segment) (E : env) (M : word -> option byte) (k1 k2 k3 k4 k5 k6 k7 k8 k9 k10 : kentry)
      (rest : list kentry),
    Forall (kentry_ok segs E M) [k1; k2; k3; k4; k5; k6; k7; k8; k9; k10] -> Forall (kentry_ok segs E M) rest ->
    Forall (kentry_ok segs E M) (k1 :: k2 :: k3 :: k4 :: k5 :: k6 :: k7 :: k8 :: k9 :: k10 :: rest).
  Proof.
    intros segs E M k1 k2 k3 k4 k5 k6 k7 k8 k9 k10 rest K1 K2.
    change (k1 :: k2 :: k3 :: k4 :: k5 :: k6 :: k7 :: k8 :: k9 :: k10 :: rest)
      with ([k1; k2; k3; k4; k5; k6; k7; k8; k9; k10] ++ rest).
    apply Forall_app. split; [exact K1 | exact K2].
  Qed.

  Lemma t1_cl : forall LBx A, ((as_FSB H <= A /\ A + 40 <= as_FSB H + AFS_SIZE) \/ spz - 96 <= A) ->
    aclient_range H LBx (spz - 96) A 40.
  Proof.
    intros LBx A [HA|HA].
    - right; right; right; right; left. exact HA.
    - left. exact HA.
  Qed.

  Lemma t1_hdr_apres : forall LBx m m' o bl bc f sz mlf pad,
    apres H LBx (spz - 96) m m' -> hdr40 m o bl bc f sz mlf pad -> aclient_range H LBx (spz - 96) o 40 ->
    hdr40 m' o bl bc f sz mlf pad.
  Proof.
    intros LBx m m' o bl bc f sz mlf pad HP HD HC. unfold hdr40 in *.
    eapply (apres_rw_cells H); [exact HP | exact HD | exact HC].
  Qed.
  Lemma mva_t1 : forall (bl1 bc1 bl2 bc2 : Z) (ents2 : list (Z * (Z * Z))) (LB LBs2 : list block) (qb1 : bptr) (junk1 : list byte)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) x10 x11 x12 x13 x14 x15 x16 x17
                             (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 2147450880) (rSh (rO o1 24)) (rSrl o1)
                             x24 x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_L1) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TS s LB bl2 bc2 ents2 LBs2 m ->
    Permutation LB (LB0 ++ (if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)]) ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    hdr40 m o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) (Z_to_bv 64 0) (Z_to_bv 64 0) (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad2 ->
    (bc1 = 0 -> bl1 = 0) ->
    (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= 26339969 /\ rw_cells asegs m bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m bl1 (8 * bc1)) ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo).
Proof.
  intros bl1 bc1 bl2 bc2 ents2 LB LBs2 qb1 junk1 x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31
    F msF mo m s pad1 pad2 VIS KR MP HTS PE AL HD1 HD2 B0 B1 U2 PM2 AP2.
  pose proof HTS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  unfold AIMG_TOP in O1a, O2a.
  pose proof AP12 as AP12u. unfold apart in AP12u.
  pose proof HD1 as HD1u. unfold hdr40 in HD1u. pose proof HD2 as HD2u. unfold hdr40 in HD2u.
  destruct (u_bnds _ _ _ _ U2) as (UB1 & UB2 & UB3 & UB4 & UB5).
  assert (GZ1 : gz m o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  assert (GZ2 : gz m o2 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD2 | change (8 * (40 / 8)) with 40; lia]).
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 (spz - 96); Z_to_bv 64 bl1; Z_to_bv 64 bc1; Z_to_bv 64 bl2]).
  assert (HR : regs_ok E srT1 R).
  { apply regs_ok_srs; [apply regs_ok_seed|].
    repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
  assert (HK1 : know_ok asegs E m KNT1).
  { unfold know_ok, KNT1.
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact O1c]|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact O2c]|].
    apply Forall_cons; [cbn [kentry_ok]; unfold estart, elenZ; evs; rewrite ?u64_of_Z by lia; cbn [a_off a_base]; lia|].
    apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ o1 40);
      [exact (proj2 HD1) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|].
    apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ o2 40);
      [exact (proj2 HD2) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs E m o2 _ 0%nat (C8 (Z_to_bv 64 bl2)));
      [exact HD2u | reflexivity | reflexivity | lia
      | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia
      | cbn; lia | cbn; lia | reflexivity]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs E m o1 _ 0%nat (C8 (Z_to_bv 64 bl1)));
      [exact HD1u | reflexivity | reflexivity | lia
      | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia
      | cbn; lia | cbn; lia | reflexivity]|].
    apply Forall_cons; [eapply (kword_of_rw_cells asegs E m o1 _ 8%nat (C8 (Z_to_bv 64 bc1)));
      [exact HD1u | reflexivity | reflexivity | lia
      | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia
      | cbn; lia | cbn; lia | reflexivity]|].
    apply Forall_nil. }
  destruct (Z.eqb_spec bc1 0) as [E0|N0].
  - cbv iota in PE.
    pose proof (B0 E0) as BL0.
    assert (HK : know_ok asegs E m (kn_fix 20 MVA_T1STOPS (SCR [] [] []) MVA_L1 srT1 (KNT1 ++ [KRange (EVar 35) 0 0]) 40)).
    { kn_eval. unfold know_ok. apply t1_kn_pre; [exact HK1|].
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA_L1 m (seg_rom asegs) HR HK 40%nat MVA_T1STOPS (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj.
      all: pose proof O2d as O2du; unfold in_app_mem in O2du; rewrite ASHADOW_BASE_val in O2du; unfold AHI_LO in O2du; sc_shdj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m LG) in Hms; set (M1 := mem_denot E m LG) in Hms end.
    assert (MU1 : munch XOB m M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|]. unfold XOB.
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (TS1 : TS s LB bl2 bc2 ents2 LBs2 M1).
    { eapply TS_hdr; [exact HTS | exact MU1 | exact WM1 | exact MI1 | exact (perm_inc3 _ _ _ _ PE) | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    destruct (hdr40_split _ _ _ _ _ _ _ _ HD1) as (P0 & P8 & P16 & P24 & P32 & P36).
    destruct (hdr40_split _ _ _ _ _ _ _ _ HD2) as (Q0 & Q8 & Q16 & Q24 & Q32 & Q36).
    assert (P0' : rw_cells asegs M1 o1 [C8 (Z_to_bv 64 bl2)]) by (unfold M1, LG; rwc_new Hlf (proj2 P0)).
    assert (Q0' : rw_cells asegs M1 o2 [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 Q0)).
    assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ P0' ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                      ltac:(unfold M1, LG; rwc_keep P16 Hlf) ltac:(unfold M1, LG; rwc_keep P24 Hlf)
                      ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
    assert (HD2' := hdr40_join M1 o2 _ _ _ _ _ _ Q0' ltac:(unfold M1, LG; rwc_keep Q8 Hlf)
                      ltac:(unfold M1, LG; rwc_keep Q16 Hlf) ltac:(unfold M1, LG; rwc_keep Q24 Hlf)
                      ltac:(unfold M1, LG; rwc_keep Q32 Hlf) ltac:(unfold M1, LG; rwc_keep Q36 Hlf)).
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
    rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23.
    rewrite G2, G8, G9, G18, G19, G20, G21, G22, G23 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply mva_t2 with (s := s) (msF := msF1) (mo := mo1) (m := M1) (LB := LB).
    + exact VIS1.
    + exact KR1.
    + eapply (ah_mpres_trans H HH); [exact MP | exact MP1].
    + exact TS1.
    + exact PE.
    + exact AL.
    + exact HD1'.
    + exact HD2'.
    + exact U2.
    + exact PM2.
    + exact AP2.
  - cbv iota in PE.
    destruct (B1 N0) as (J0 & J1 & J2 & J3).
    pose proof LOH as (LOH1 & LOH2). unfold AFREE_STACK in LOH2.
    assert (INb : In (qb1, bl1, 8 * bc1) LB) by exact (perm_in_mid _ _ _ _ PE).
    pose proof (ah_blocks H HH _ _ _ (qb1, bl1, 8 * bc1) RH INb) as (Hq0 & Hq16 & Hqn & HqI & HqC & HqF & HqA).
    unfold blk_addr, blk_size in Hq0, Hq16, Hqn, HqI, HqC, HqF, HqA. cbn [fst snd] in Hq0, Hq16, Hqn, HqI, HqC, HqF, HqA.
    assert (HK : know_ok asegs E m (kn_fix 20 MVA_T1STOPS (SCR [] [] []) MVA_L1 srT1 (KNT1 ++ [KRange (EVar 35) 1 (2 ^ 47)]) 40)).
    { kn_eval. unfold know_ok. apply t1_kn_pre; [exact HK1|].
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA_L1 m (seg_rom asegs) HR HK 40%nat MVA_T1STOPS (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj.
      all: pose proof O1d as O1du; pose proof O2d as O2du; unfold in_app_mem in O1du, O2du;
        rewrite ASHADOW_BASE_val in O1du, O2du; unfold AHI_LO in O1du, O2du; sc_shdj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m LG) in Hms; set (M1 := mem_denot E m LG) in Hms end.
    assert (MU1 : munch XOB m M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|]. unfold XOB.
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (TS1 : TS s LB bl2 bc2 ents2 LBs2 M1).
    { eapply TS_hdr; [exact HTS | exact MU1 | exact WM1 | exact MI1 | exact (perm_inc3 _ _ _ _ PE) | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    destruct (hdr40_split _ _ _ _ _ _ _ _ HD1) as (P0 & P8 & P16 & P24 & P32 & P36).
    destruct (hdr40_split _ _ _ _ _ _ _ _ HD2) as (Q0 & Q8 & Q16 & Q24 & Q32 & Q36).
    assert (P0' : rw_cells asegs M1 o1 [C8 (Z_to_bv 64 bl2)]) by (unfold M1, LG; rwc_new Hlf (proj2 P0)).
    assert (Q0' : rw_cells asegs M1 o2 [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 Q0)).
    assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ P0' ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                      ltac:(unfold M1, LG; rwc_keep P16 Hlf) ltac:(unfold M1, LG; rwc_keep P24 Hlf)
                      ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
    assert (HD2' := hdr40_join M1 o2 _ _ _ _ _ _ Q0' ltac:(unfold M1, LG; rwc_keep Q8 Hlf)
                      ltac:(unfold M1, LG; rwc_keep Q16 Hlf) ltac:(unfold M1, LG; rwc_keep Q24 Hlf)
                      ltac:(unfold M1, LG; rwc_keep Q32 Hlf) ltac:(unfold M1, LG; rwc_keep Q36 Hlf)).
    assert (CB1 : rw_cells asegs M1 bl1 [CB (Z.to_nat (8 * bc1)) junk1]).
    { eapply rw_cells_transport; [exact J2 | exact MU1 | exact WM1 |].
      unfold XOB. cbn [disjoint_from cells_size csize]. rewrite Nat.add_0_r, Z2Nat.id by lia. repeat split; lia. }
    assert (ADb : addressable M1 bl1 (8 * bc1)) by (eapply addressable_transport; [exact J3 | exact MU1 | exact WM1 | apply dsh_xob; lia]).
    pose proof TS1 as (MI1' & ST1 & ERR1 & RA1 & AC1 & RF1 & S01 & RH1 & FR1 & AD11 & AD21 & USH1 & XP1 & OWN1).
    assert (ST1' : stk asegs M1 lo (spz - 96)) by exact (proj1 (stk_split asegs M1 lo (spz - 96) spz ST1 ltac:(lia))).
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 1%bv G1. rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10.
    rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23.
    rewrite G1, G2, G8, G9, G18, G19, G20, G21, G22, G23 in HRe.
    assert (G4 : getr R' 4 = tp) by (rewrite HRe; reflexivity).
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    eapply (ah_seq H HH).
    { eapply (ah_opdel2 H HH) with (p := qb1) (A := bl1) (n := 8 * bc1) (LB := LB) (lo := lo) (B := B) (errv := errv) (CH := [])
        (sbs := shadow_of (8 * bc1)) (bs := junk1);
      [ exact VIS1 | exact RH1 | exact KR1 | exact INb | rewrite HCF; lia | exact CB1 | exact (proj2 ADb)
      | rewrite shadow_of_length by lia; reflexivity
      | exact RA1 | rewrite G2, u64_of_Z by lia; lia | rewrite G2, u64_of_Z by lia; exact ST1' | lia
      | rewrite G2, u64_of_Z by lia; lia | rewrite G4; exact ERR1 | exact MI1 | rewrite G4; exact TPV
      | rewrite G2, u64_of_Z by lia; replace (spz - 96) with (spz + (-6) * 16) by lia; rewrite Z_mod_plus_full; exact SPZ16
      | exact AC1
      | rewrite G8, w_add, u64_of_Z by lia; apply (ah_chain_nil H HH); left; lia
      | rewrite G1; cbn [map]; rewrite u64_of_Z by lia; exact TRK2
      | exact G10 ]. }
    intros [msF2 mo2] POST2.
    destruct POST2 as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m2 & s'
                       & VIS2 & KR2 & MP2 & MI2 & ST2 & ERR2 & RA2 & APR2 & RH2 & AC2 & AL2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite G2, u64_of_Z in ST2, APR2 by lia. rewrite G4 in ERR2.
    rewrite G1 in VIS2. rewrite ret_pc_even in VIS2 by first [reflexivity | lia].
    rewrite HRe in VIS2.
    set (LB' := as_lb_remove H qb1 LB) in *.
    pose proof (ah_nodup H HH _ _ _ RH) as ND.
    assert (PL : Permutation LB' (LB0 ++ LBs2)) by exact (lb_remove_perm_app H HH LB LB0 LBs2 qb1 bl1 (8 * bc1) ND PE).
    assert (TS2 : TS s' LB' bl2 bc2 ents2 LBs2 m2).
    { eapply TS_free; [exact TS1 | exact APR2 | exact RH2 | | exact MI2 | exact ST2 | exact ERR2 | exact RA2 | exact AC2 | | | ].
      - intros b Hb. exact (Permutation_in _ (Permutation_sym PL) Hb).
      - intros b Hb. apply (Permutation_in _ (Permutation_sym PL)). apply in_or_app. right. exact Hb.
      - intros A n Hin. exact (Permutation_in _ (Permutation_sym PM2) Hin).
      - intros b Hb. apply (perm_inc3 _ _ _ _ PE). exact (Permutation_in _ PL Hb). }
    assert (CL1 : aclient_range H LB' (spz - 96) o1 40) by (apply t1_cl; left; exact FS1).
    assert (CL2 : aclient_range H LB' (spz - 96) o2 40).
    { apply t1_cl. destruct FS2 as [F2|F2]; [left; exact F2 | right; lia]. }
    pose proof (t1_hdr_apres _ _ _ _ _ _ _ _ _ _ APR2 HD1' CL1) as HD1''.
    pose proof (t1_hdr_apres _ _ _ _ _ _ _ _ _ _ APR2 HD2' CL2) as HD2''.
    eapply mva_t2 with (s := s') (msF := msF2) (mo := mo2) (m := m2) (LB := LB').
    + exact VIS2.
    + exact KR2.
    + eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]].
    + exact TS2.
    + exact PL.
    + rewrite HCF in AL2. lia.
    + exact HD1''.
    + exact HD2''.
    + exact U2.
    + exact PM2.
    + exact AP2.
Qed.

  Lemma mva_l2m : forall (bl1 bc1 bl2 bc2 : Z) (wz1 : word) (ents2 : list (Z * (Z * Z))) (LB LBs2 : list block) (qb1 : bptr) (junk1 : list byte)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) x10 x11 x12 x13 x14 x15 x16 x17
                             (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 2147450880) (rSh (rO o1 24)) (rSrl o1)
                             x24 x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_L2M) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TS s LB bl2 bc2 ents2 LBs2 m ->
    Permutation LB (LB0 ++ (if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)]) ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    hdr40 m o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) (Z_to_bv 64 0) wz1 (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad2 ->
    (bc1 = 0 -> bl1 = 0) ->
    (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= 26339969 /\ rw_cells asegs m bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m bl1 (8 * bc1)) ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo).
Proof.
  intros bl1 bc1 bl2 bc2 wz1 ents2 LB LBs2 qb1 junk1 x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x24 x25 x28 x29 x30 x31
    F msF mo m s pad1 pad2 VIS KR MP HTS PE AL HD1 HD2 B0 B1 U2 PM2 AP2.
  pose proof HTS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  unfold AIMG_TOP in O1a, O2a.
  destruct (u_bnds _ _ _ _ U2) as (UB1 & UB2 & UB3 & UB4 & UB5).
  assert (GZ1 : gz m o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 (spz - 96)]).
  assert (HR : regs_ok E srT1 R).
  { apply regs_ok_srs; [apply regs_ok_seed|].
    repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
  assert (HK : know_ok asegs E m (kn_fix 20 [MVA_L1] (SCR [] [] []) MVA_L2M srT1 KNL2M 40)).
  { kn_eval. unfold know_ok.
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
    apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact O1c]|].
    apply Forall_cons; [eapply (kwr_of_wr_at asegs _ _ o1 40); [exact (proj2 HD1) | rwc_norm | unfold elenZ; rwc_norm | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]|].
    know_tac. }
  xrun_at (PropExec.mkFP F fc) asegs R MVA_L2M m (seg_rom asegs) HR HK 20%nat [MVA_L1] (SCR [] [] []) 40%N.
  { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
  lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
  lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
    change mm with (mem_denot E m LG) in Hms; set (M1 := mem_denot E m LG) in Hms end.
  assert (MU1 : munch XOB m M1).
  { subst M1. apply munch_mem_denot; [exact Hlf|]. unfold XOB.
