  assert (P24' : rw_cells asegs M1 (o1 + 24) [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 P24)).
  assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ ltac:(unfold M1, LG; rwc_keep P0 Hlf) ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                    ltac:(unfold M1, LG; rwc_keep P16 Hlf) P24' ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
  assert (DJ2 : disjoint_from (log_ivs E LG) o2 40).
  { subst LG; unfold log_ivs; cbn [map disjoint_from e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia;
    cbn [a_off a_base Z.of_nat]; unfold apart in AP12; repeat split; lia. }
  pose proof (hdr40_transport _ _ _ _ _ _ _ _ _ _ HD2 (munch_log E m _ Hlf) (wmono_mem_denot E m _) DJ2) as HD2'.
  assert (JT : bc1 <> 0 -> rw_cells asegs M1 bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable M1 bl1 (8 * bc1)).
  { intros Hb. destruct (B1 Hb) as (J0 & J1 & J2 & J3).
