    - eapply addressable_transport; [exact J3 | exact MU1 | exact WM1 | apply dsh_xob; lia]. }
  assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
  readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
  rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
  rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23.
  rewrite G2, G8, G9, G18, G19, G20, G21, G22, G23 in HRe.
  eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
  intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
  eapply mva_t1 with (s := s) (msF := msF1) (mo := mo1) (m := M1).
  - exact VIS1.
  - exact KR1.
  - eapply (ah_mpres_trans H HH); [exact MP | exact MP1].
  - exact TS1.
  - exact PE.
  - exact AL.
  - exact HD1'.
  - exact HD2'.
  - exact B0.
  - intros Hb. destruct (B1 Hb) as (X1 & X2 & _ & _). destruct (JT Hb) as (X3 & X4).
    split; [exact X1|]. split; [exact X2|]. split; [exact X3 | exact X4].
