    Z.of_nat n = bc1 - i ->
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) x10
                             (Z_to_bv 64 bc1) (Z_to_bv 64 bl1) (Z_to_bv 64 (8 * i)) (Z_to_bv 64 i) (Z_to_bv 64 (2 ^ 64 - 1 - bl1)) x16 x17
