    0 <= i < bc1 -> bc1 <= 2 ^ 40 -> 0 < bl1 -> bl1 mod 8 = 0 -> bl1 + 8 * bc1 <= 2 ^ 47 ->
    (bl1 + 8 * bc1 <= SHBASE \/ AHI_LO <= bl1) ->
