    (forall (msF' : machine_state) (mo' : Model) (m' : mem) (y10 y11 y12 y13 y14 y15 y16 y17 : word),
       as_VIS H s msF' = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1)
                                 y10 y11 y12 y13 y14 y15 y16 y17
                                 (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 SHBASE) (rSh (rO o1 24)) (rSrl o1)
                                 x24 x25 s10 s11 x28 x29 x30 x31)
