    F msF mo m s pad1 pad2 VIS KR MP HTS PE AL HD1 HD2 B0 B1 U2 PM2 AP2.
  pose proof HTS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  unfold AIMG_TOP in O1a, O2a.
  pose proof AP12 as AP. unfold apart in AP.
  destruct (u_bnds _ _ _ _ U2) as (UB1 & UB2 & UB3 & UB4 & UB5).
  assert (GZ1 : gz m o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  assert (INC : forall b, In b (LB0 ++ LBs2) -> In b LB).
  { intros b Hb. apply (Permutation_in _ (Permutation_sym PE)). apply in_app_or in Hb.
    destruct Hb as [Hb|Hb]; apply in_or_app; [left; exact Hb | right; apply in_or_app; right; exact Hb]. }
  assert (O1S : o1 + 24 <= SHBASE \/ AHI_LO <= o1 + 16).
  { unfold in_app_mem in O1d. pose proof ASHADOW_BASE_val. unfold SHBASE. lia. }
  pose proof O1S as O1N. unfold SHBASE, AHI_LO in O1N.
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 (spz - 96); Z_to_bv 64 bl1; Z_to_bv 64 bc1]).
  assert (HR : regs_ok E l2_srA R).
  { apply regs_ok_srs; [apply regs_ok_seed|].
    repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]).
    apply Forall_nil. }
  assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
  destruct (hdr40_split _ _ _ _ _ _ _ _ HD1) as (P0 & P8 & P16 & P24 & P32 & P36).
  destruct (Z.eq_dec bc1 0) as [Hz|Hz].
  - pose proof (B0 Hz) as Hl0.
    assert (HK : know_ok asegs E m (kn_fix 20 [MVA_L2M; l2_LH] (SCR [] [] []) MVA_L2 l2_srA l2_KE0 40)).
    { kn_eval. unfold know_ok. l2_kn5 HD1 O1c.
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA_L2 m (seg_rom asegs) HR HK 40%nat [MVA_L2M; l2_LH] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m LG) in Hms; set (M1 := mem_denot E m LG) in Hms end.
    assert (MU1 : munch [(o1 + 16, o1 + 24)] m M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (TS1 : TS s LB bl2 bc2 ents2 LBs2 M1).
    { eapply TS_munch; [exact HTS | exact MU1 | exact WM1 | exact MI1 | apply Forall_cons; [unfold wT; left; cbn [fst snd]; lia | apply Forall_nil]
        | exact INC | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    assert (P16' : rw_cells asegs M1 (o1 + 16) [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 P16)).
    assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ ltac:(unfold M1, LG; rwc_keep P0 Hlf) ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                      P16' ltac:(unfold M1, LG; rwc_keep P24 Hlf) ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
    pose proof (hdr40_transport _ _ _ _ _ _ _ _ _ _ HD2 MU1 WM1 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD2'.
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20. rreg HR' 21%bv G21.
    rreg HR' 22%bv G22. rreg HR' 23%bv G23. rreg HR' 24%bv G24.
    rewrite G2, G8, G9, G18, G19, G20, G21, G22, G23, G24 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply mva_l2m with (s := s) (msF := msF1) (mo := mo1) (m := M1) (junk1 := junk1).
    + exact VIS1.
    + exact KR1.
    + eapply (ah_mpres_trans H HH); [exact MP | exact MP1].
    + exact TS1.
    + exact PE.
    + exact AL.
    + exact HD1'.
    + exact HD2'.
    + exact B0.
    + intros Hb. contradiction.
    + exact U2.
    + exact PM2.
    + exact AP2.
  - destruct (B1 Hz) as (J0 & J1 & J2 & J3).
    assert (INb : In (qb1, bl1, 8 * bc1) LB).
    { apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. apply in_or_app. left.
      destruct (Z.eqb_spec bc1 0); [lia | left; reflexivity]. }
    pose proof (ah_blocks H HH _ _ _ (qb1, bl1, 8 * bc1) RH INb) as (Hq0 & Hq16 & Hqn & HqI & HqC & HqF & HqA).
    unfold blk_addr, blk_size in Hq0, Hq16, Hqn, HqI, HqC, HqF, HqA. cbn [fst snd] in Hq0, Hq16, Hqn, HqI, HqC, HqF, HqA.
    assert (Hb8 : bl1 mod 8 = 0).
    { rewrite <- (Z.mod_mod_divide bl1 16 8 ltac:(exists 2; reflexivity)), Hq16. reflexivity. }
    assert (Hba : bl1 + 8 * bc1 <= SHBASE \/ AHI_LO <= bl1) by (unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO in HqA; unfold SHBASE; lia).
    assert (HK : know_ok asegs E m (kn_fix 20 [MVA_L2M; l2_LH] (SCR [] [] []) MVA_L2 l2_srA l2_KE1 40)).
    { kn_eval. unfold know_ok. l2_kn5 HD1 O1c.
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|].
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; unfold AIMG_TOP in HqI; lia|].
      apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; split; [lia | exact Hb8]|].
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA_L2 m (seg_rom asegs) HR HK 40%nat [MVA_L2M; l2_LH] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m LG) in Hms; set (M1 := mem_denot E m LG) in Hms end.
    assert (MU1 : munch [(o1 + 16, o1 + 24)] m M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (TS1 : TS s LB bl2 bc2 ents2 LBs2 M1).
    { eapply TS_munch; [exact HTS | exact MU1 | exact WM1 | exact MI1 | apply Forall_cons; [unfold wT; left; cbn [fst snd]; lia | apply Forall_nil]
        | exact INC | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    assert (P16' : rw_cells asegs M1 (o1 + 16) [C8 (Z_to_bv 64 0)]) by (unfold M1, LG; rwc_new Hlf (proj2 P16)).
    assert (HD1' := hdr40_join M1 o1 _ _ _ _ _ _ ltac:(unfold M1, LG; rwc_keep P0 Hlf) ltac:(unfold M1, LG; rwc_keep P8 Hlf)
                      P16' ltac:(unfold M1, LG; rwc_keep P24 Hlf) ltac:(unfold M1, LG; rwc_keep P32 Hlf) ltac:(unfold M1, LG; rwc_keep P36 Hlf)).
    pose proof (hdr40_transport _ _ _ _ _ _ _ _ _ _ HD2 MU1 WM1 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD2'.
    assert (ADM1 : addressable M1 bl1 (8 * bc1)).
    { eapply addressable_transport; [exact J3 | exact MU1 | exact WM1 | apply l2_dsh; lia]. }
    assert (WR1 : wr_at asegs M1 bl1 (8 * bc1)) by exact (wr_at_wmono _ _ _ _ (own_of_rw_cells _ _ _ _ J2 ltac:(lia)) WM1).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 11%bv G11. rreg HR' 12%bv G12. rreg HR' 13%bv G13. rreg HR' 14%bv G14.
    rreg HR' 15%bv G15. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22.
    rreg HR' 23%bv G23. rreg HR' 24%bv G24.
    rewrite l2_negm1 in G15 by lia.
    rewrite G2, G8, G9, G11, G12, G13, G14, G15, G18, G19, G20, G21, G22, G23, G24 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply (l2_loop (Z.to_nat bc1) _ 0 bl1 bc1); [rewrite Z2Nat.id by lia; lia | exact VIS1 | exact KR1 | lia | lia | lia | exact Hb8 | lia
      | exact Hba | exact WR1 | exact ADM1 | exact MI1 |].
    intros msF2 mo2 M2 y10 y11 y12 y13 y14 y15 y16 y17 VIS2 KR2 MP2 MU2 WM2 MI2.
    assert (PE2 : Permutation LB ((LB0 ++ LBs2) ++ [(qb1, bl1, 8 * bc1)])).
    { rewrite (proj2 (Z.eqb_neq bc1 0) Hz) in PE.
      eapply Permutation_trans; [exact PE|]. rewrite <- app_assoc. apply Permutation_app_head. apply Permutation_app_comm. }
    assert (TS2 : TS s LB bl2 bc2 ents2 LBs2 M2).
    { eapply (TS_munchB s LB bl2 bc2 ents2 LBs2 M1 M2 [(bl1, bl1 + 8 * bc1)] qb1 bl1 (8 * bc1));
        [exact TS1 | exact MU2 | exact WM2 | exact MI2 | apply Forall_cons; [right; cbn [fst snd]; lia | apply Forall_nil] | exact PE2
        | exact UB1 | exact UB2 | exact UB3 | exact UB4 | exact UB5]. }
    pose proof (hdr40_transport _ _ _ _ _ _ _ _ _ _ HD1' MU2 WM2 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD1''.
    pose proof (hdr40_transport _ _ _ _ _ _ _ _ _ _ HD2' MU2 WM2 ltac:(cbn [disjoint_from]; split; [lia | exact I])) as HD2''.
    assert (ADM2 : addressable M2 bl1 (8 * bc1)).
    { eapply addressable_transport; [exact ADM1 | exact MU2 | exact WM2 | apply l2_dsh; lia]. }
    pose proof TS2 as (_ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & _ & OWN2).
    destruct (rw_cells_of_own LB M2 (qb1, bl1, 8 * bc1) OWN2 INb ltac:(cbn; exact HqI) ltac:(cbn; lia)) as (bs & CBS).
    unfold blk_addr, blk_size in CBS. cbn [fst snd] in CBS.
    eapply mva_l2m with (s := s) (msF := msF2) (mo := mo2) (m := M2) (junk1 := bs).
    + exact VIS2.
    + exact KR2.
    + eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]].
    + exact TS2.
    + exact PE.
    + exact AL.
    + exact HD1''.
    + exact HD2''.
    + exact B0.
    + intros _. split; [exact J0|]. split; [exact J1|]. split; [exact CBS | exact ADM2].
    + exact U2.
    + exact PM2.
    + exact AP2.
Qed.

  Fixpoint nodes_okA (LBn : list block) (m : mem) (ns : list (Z * list byte)) : Prop :=
    match LBn, ns with
    | [], [] => True
    | b :: LBn', (q, tl) :: ns' =>
        blk_addr b = q /\ blk_size b = 24
        /\ rw_cells asegs m q [C8 (Z_to_bv 64 (match ns' with [] => 0 | (q', _) :: _ => q' end)); CB 16 tl]
        /\ addressable m q 24
        /\ (match ns' with [] => True | (q', _) :: _ => 0x6e8000 <= q' < 2 ^ 47 end)
        /\ nodes_okA LBn' m ns'
    | _, _ => False
    end.

