  Lemma ent_rO : forall o k, 0 <= o -> 0 <= k -> o + k < 2 ^ 64 -> bv_unsigned (rO o k) = o + k.
  Proof.
    intros o k Ho Hk Hok. unfold rO. rewrite alu_add. unfold v_add.
    rewrite (u64_of_Z o) by lia. rewrite (u64_of_Z k) by lia. rewrite u64_of_Z by lia. reflexivity.
  Qed.

  Lemma ent_step : forall (Q : config -> Prop) (ns : list (Z * list byte)) (q : Z) (tl : list byte) (b0 : block) (LBn : list block)
      (bl1 bc1 bl2 bc2 K : Z) (wf1 wz1 mlf : word) (ents2 : list (Z * (Z * Z))) (LB LBs2 LBj : list block)
      (qb1 : bptr) (junk1 : list byte)
      (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) (Z_to_bv 64 q) x11 x12 x13 x14 x15 x16 x17
                             (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 SHBASE) (rSh (rO o1 24)) (rSrl o1)
                             (rSh (rO o1 16)) x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_LOOP) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TS s LB bl2 bc2 ents2 LBs2 m ->
    LBj = (if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)]) ->
    Permutation LB ((LB0 ++ LBj) ++ b0 :: LBn ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    nodes_okA (b0 :: LBn) m ((q, tl) :: ns) ->
    hdr40 m o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) wf1 wz1 mlf pad1 ->
    hdr40 m o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) mlf pad2 ->
    (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= K /\ rw_cells asegs m bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m bl1 (8 * bc1)) ->
    Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall (msF' : machine_state) (mo' : Model) (m' : mem) (s' : as_St H) (LB' : list block)
            (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
       as_VIS H s' msF' = MS (mkR (Z_to_bv 64 MVA_DRET1) (Z_to_bv 64 (spz - 96)) gp tp t0 t1 t2 (rO o1 16) (Z_to_bv 64 o1)
                                 (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) a1 a2 a3 a4 a5 a6 a7
                                 (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 SHBASE) (rSh (rO o1 24)) (rSrl o1)
                                 (rSh (rO o1 16)) (Z_to_bv 64 (match ns with [] => 0 | (q', _) :: _ => q' end)) s10 s11 t3 t4 t5 t6)
                            F (Z_to_bv 64 (match ns with [] => MVA_L2 | _ => MVA_LOOP end)) fc None m' (seg_rom asegs) ->
       as_AKREL H s' (mkCfg msF' mo') -> as_MPRES H mo0 mo' ->
       TS s' LB' bl2 bc2 ents2 LBs2 m' ->
       Permutation LB' ((LB0 ++ LBj) ++ LBn ++ LBs2) -> as_AL H s' >= as_AL H st0 ->
       nodes_okA LBn m' ns ->
       hdr40 m' o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) wf1 wz1 mlf pad1 ->
       hdr40 m' o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) mlf pad2 ->
       (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= K /\ rw_cells asegs m' bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m' bl1 (8 * bc1)) ->
       as_SR H Q (mkCfg msF' mo')) ->
    as_SR H Q (mkCfg msF mo).
  Proof.
    intros Q ns q tl b0 LBn bl1 bc1 bl2 bc2 K wf1 wz1 mlf ents2 LB LBs2 LBj qb1 junk1
      x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x25 x28 x29 x30 x31 F msF mo m s pad1 pad2
      VIS KR MP HTS HJ PE AL NOK HD1 HD2 B1 PM2 KC.
    destruct b0 as [[id a] sz]. cbn [nodes_okA] in NOK. unfold blk_addr, blk_size in NOK. cbn [fst snd] in NOK.
    destruct NOK as (-> & -> & CQ & ADQ & NXR & NOK).
    pose proof HTS as (MI & ST & ERR & RA & AC & RF & S0 & RH & FR & AD1 & AD2 & USH & XP & OWN).
    pose proof O1R as (O1a & O1b & O1c & O1d).
    pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
    pose proof SPZR as (SPa & SPb).
    pose proof LOH as (LOa & LOb). unfold AFREE_STACK in LOb.
    pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
    unfold AIMG_TOP in O1a, O2a.
    destruct (stk_split asegs m lo (spz - 96) spz ST ltac:(lia)) as (ST1 & _).
    pose proof (ah_nodup H HH _ _ _ RH) as ND.
    assert (INq : In (id, q, 24) LB).
    { apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. left. reflexivity. }
    pose proof (lb_remove_perm_app H HH LB (LB0 ++ LBj) (LBn ++ LBs2) id q 24 ND PE) as PE'.
    pose proof (lb_remove_perm H HH LB id q 24 ND INq) as P1.
    assert (SUB : forall b, In b (as_lb_remove H id LB) -> In b LB).
    { intros b Hb. apply (Permutation_in _ (Permutation_sym P1)). right. exact Hb. }
    assert (INr : forall b, In b ((LB0 ++ LBj) ++ LBn ++ LBs2) -> In b (as_lb_remove H id LB)).
    { intros b Hb. exact (Permutation_in _ (Permutation_sym PE') Hb). }
    eapply (mva_loop_step H HH) with (spf := spz - 96) (lo := lo) (B := B) (errv := errv) (id := id) (tl := tl) (ns := ns) (LB := LB);
      [ exact VIS | exact INq | exact CQ | exact ADQ | exact RH | exact KR | rewrite HCF; lia | exact RA | lia | exact ST1
      | lia | unfold AFREE_STACK; lia | exact ERR | exact MI | exact TPV
      | replace (spz - 96) with (spz + (-6) * 16) by lia; rewrite Z_mod_plus_full; exact SPZ16
      | lia | exact AC | left; rewrite ent_rO by lia; lia | exact TRK1 | exact NXR | ].
    intros msF' mo' m' s' t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 VIS' KR' MP' MI' ST' ERR' RA' AP RH' AC' AL'.
    pose proof FS1 as (F1a & F1b).
    eapply (KC msF' mo' m' s' (as_lb_remove H id LB)); [exact VIS' | exact KR' | exact (ah_mpres_trans H HH _ _ _ MP MP') | | exact PE' | | | | | ].
    - eapply TS_free; [exact HTS | exact AP | exact RH' | | exact MI' | exact ST' | exact ERR' | exact RA' | exact AC' | | | exact SUB].
      + intros b Hb. apply INr. apply in_app_or in Hb. destruct Hb as [Hb|Hb].
        * apply in_or_app. left. apply in_or_app. left. exact Hb.
        * apply in_or_app. right. apply in_or_app. right. exact Hb.
      + intros b Hb. apply INr. apply in_or_app. right. apply in_or_app. right. exact Hb.
      + intros A n Hb. exact (Permutation_in _ (Permutation_sym PM2) Hb).
    - rewrite HCF in AL'. lia.
    - eapply nodes_okA_apres; [exact NOK | exact AP |].
      intros b Hb. apply INr. apply in_or_app. right. apply in_or_app. left. exact Hb.
    - unfold hdr40 in *. eapply (apres_rw_cells H); [exact AP | exact HD1 |].
