  Lemma mva_loop : forall (ns : list (Z * list byte)) (q : Z) (tl : list byte) (b0 : block) (LBn : list block)
      (bl1 bc1 bl2 bc2 : Z) (wf1 wz1 : word) (ents2 : list (Z * (Z * Z))) (LB LBs2 : list block) (qb1 : bptr) (junk1 : list byte)
      (x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x25 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (msF : machine_state) (mo : Model) (m : mem) (s : as_St H) (pad1 pad2 : list byte),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 (spz - 96)) gp tp x5 x6 x7 (rO o1 16) (Z_to_bv 64 o1) (Z_to_bv 64 q) x11 x12 x13 x14 x15 x16 x17
                             (rO o1 8) (Z_to_bv 64 o2) (rO o1 24) (Z_to_bv 64 2147450880) (rSh (rO o1 24)) (rSrl o1)
                             (rSh (rO o1 16)) x25 s10 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 MVA_LOOP) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    TS s LB bl2 bc2 ents2 LBs2 m ->
    Permutation LB ((LB0 ++ (if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)])) ++ b0 :: LBn ++ LBs2) -> as_AL H s >= as_AL H st0 ->
    nodes_okA (b0 :: LBn) m ((q, tl) :: ns) ->
    hdr40 m o1 (Z_to_bv 64 bl1) (Z_to_bv 64 bc1) wf1 wz1 (Z_to_bv 64 0x3f800000) pad1 ->
    hdr40 m o2 (Z_to_bv 64 bl2) (Z_to_bv 64 bc2) (Z_to_bv 64 (hdaddr ents2)) (Z_to_bv 64 (Zlength ents2)) (Z_to_bv 64 0x3f800000) pad2 ->
    (bc1 = 0 -> bl1 = 0) ->
    (bc1 <> 0 -> 0 < bl1 /\ 0 < bc1 <= 26339969 /\ rw_cells asegs m bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m bl1 (8 * bc1)) ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo).
Proof.
  intros ns. induction ns as [|[q' tl'] ns IH];
    intros q tl b0 LBn bl1 bc1 bl2 bc2 wf1 wz1 ents2 LB LBs2 qb1 junk1
      x1 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x25 x28 x29 x30 x31 F msF mo m s pad1 pad2
      VIS KR MP HTS PE AL NOK HD1 HD2 B0 B1 U2 PM2 AP2;
    (eapply (ent_step _ _ q tl b0 LBn bl1 bc1 bl2 bc2 _ wf1 wz1 _ ents2 LB LBs2 _ qb1 junk1);
      [ exact VIS | exact KR | exact MP | exact HTS | reflexivity | exact PE | exact AL | exact NOK
      | exact HD1 | exact HD2 | exact B1 | exact PM2 | ]);
    intros msF' mo' m' s' LB' t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 VIS' KR' MP' HTS' PE' AL' NOK' HD1' HD2' B1'.
  - destruct LBn as [|b1 LBn]; [|destruct NOK'].
    rewrite <- app_assoc in PE'.
    eapply mva_l2;
      [ exact VIS' | exact KR' | exact MP' | exact HTS' | exact PE' | exact AL' | exact HD1' | exact HD2'
      | exact B0 | exact B1' | exact U2 | exact PM2 | exact AP2 ].
  - destruct LBn as [|b1 LBn]; [destruct NOK'|].
    eapply IH;
      [ exact VIS' | exact KR' | exact MP' | exact HTS' | exact PE' | exact AL' | exact NOK' | exact HD1' | exact HD2'
      | exact B0 | exact B1' | exact U2 | exact PM2 | exact AP2 ].
Qed.

