  Definition ent_sr : list expr := srs sr_id [(10%bv, EVar 32); (11%bv, EVar 33); (2%bv, EVar 34)].
  Definition ent_KN0 : list kentry :=
    [KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit SHBASE);
     KWr (SA (EVar 34) (-96)) (ELit 96)].
  Definition ent_tl : list expr :=
    [EVar 25; EVar 24; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18; EVar 9; EVar 8; EVar 1].

  Lemma ent_relive : forall (A A' : list (Z * Z)) M obj bl bc (ents : list (Z * (Z * Z))),
    umapx MI_A 24 (nval24 ASEGS) A M obj bl bc ents ->
    (forall p n, In (p, n) (umap_blocks 24 bl bc ents) -> In (p, n) A') ->
    umapx MI_A 24 (nval24 ASEGS) A' M obj bl bc ents.
  Proof.
    intros A A' M obj bl bc ents U HA.
    destruct U as [HD Hoal Holo Hohi Hbseq Hload Hblive Hblal Hbllo Hblhi Hblobj Hbkt Hndup Hch Hnode Hapart].
    constructor; try assumption.
    - destruct Hblive as [Hb|[Hb _]]; [left; exact Hb | right; split; [exact Hb|]].
      change (In (bl, 8 * bc) A'). apply HA. unfold umap_blocks. apply in_or_app. left.
      destruct (Z.eqb_spec bc 0) as [E0|E0]; [contradiction | left; reflexivity].
    - intros p k v Hi. destruct (Hnode p k v Hi) as (_ & Hrest). split; [|exact Hrest].
      change (In (p, 24) A'). apply HA. unfold umap_blocks. apply in_or_app. right.
      apply in_map_iff. exists (p, (k, v)). split; [reflexivity | exact Hi].
  Qed.

  Lemma ent_split : forall (LBs1 : list block) bl1 bc1 (ents1 : list (Z * (Z * Z))),
    Permutation (lbl LBs1) (umap_blocks 24 bl1 bc1 ents1) ->
    exists (qb1 : bptr) (LBn : list block), Permutation LBs1 ((if bc1 =? 0 then [] else [(qb1, bl1, 8 * bc1)]) ++ LBn)
      /\ lbl LBn = map (fun e => (fst e, 24)) ents1.
  Proof.
    intros LBs1 bl1 bc1 ents1 P. unfold umap_blocks in P.
    destruct (lbl_perm_split LBs1 _ _ P) as (L1 & L2 & P12 & E1 & E2).
    destruct (bc1 =? 0).
    - destruct L1 as [|b L1]; [|discriminate E1].
      exists 0, L2. split; [exact P12 | exact E2].
    - destruct L1 as [|b L1]; [discriminate E1|].
      destruct (lbl_cons_inv b L1 _ _ _ E1) as (Ea & Es & El).
      destruct L1 as [|b' L1]; [|discriminate El].
      destruct b as [[p A] n]. unfold blk_addr, blk_size in Ea, Es. cbn [fst snd] in Ea, Es. subst A n.
      exists p, L2. split; [exact P12 | exact E2].
  Qed.

  Lemma ent_mem : forall (LB LBs1 LBs2 : list block) bl2 bc2 (ents2 : list (Z * (Z * Z))) m1,
    mem_inv asegs m0 -> rw_cells asegs m0 (errno_addr tp) [C4 errv] -> as_rauxv_ok H m0 B ->
    ACONST m0 -> as_RFS H LF m0 -> stack0 m0 lo shi -> as_RHEAP H st0 LB m0 -> lb_own LB m0 ->
    addressable m0 o1 40 -> addressable m0 o2 40 -> umap_sh m0 24 (bl2, bc2, ents2) ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2 ->
    Permutation LB (LB0 ++ LBs1 ++ LBs2) ->
    munch [(spz - 96, spz)] m0 m1 -> wmono asegs m0 m1 -> mem_inv asegs m1 -> stk asegs m1 lo spz ->
    mva_frame m1 (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 ->
    TS st0 LB bl2 bc2 ents2 LBs2 m1 /\ apres H LB spz m0 m1.
  Proof.
    intros LB LBs1 LBs2 bl2 bc2 ents2 m1 MI ERR RA AC RF S0 RH OWN AD1 AD2 USH U2 PE MU WM MI1 ST1 FR.
    pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
    pose proof SPZR as (SPa & SPb). pose proof LOH as (LOa & LOb). unfold AFREE_STACK in LOb.
    pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
    unfold AIMG_TOP in O1a, O2a.
    destruct (u_bnds _ _ _ _ U2) as (UB1 & UB2 & UB3 & UB4 & UB5).
    pose proof (ah_fsb H HH _ _ _ RH) as (FB1 & FB2 & FB3 & FB4).
    assert (W1 : aclient_write_ok H LB (spz - 96, spz)) by (left; cbn [fst]; lia).
    assert (W2 : afs_write_ok H LF (spz - 96, spz)).
    { left. cbn [fst snd]. unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP. lia. }
    assert (SHT : sh AIMG_TOP <= 2 ^ 45) by (apply Z.leb_le; vm_compute; reflexivity).
    assert (W3 : aconst_ok (spz - 96, spz)) by (apply aconst_ok_high; [lia | right; left; lia]).
    assert (W4 : stack0_ok (spz - 96, spz)) by (left; cbn [fst]; unfold AHI_LO; lia).
    destruct (client_frame H HH st0 LB LF B [(spz - 96, spz)] m0 m1 RH RF AC RA MU WM
               (Forall_cons _ _ _ W1 (Forall_nil _)) (Forall_cons _ _ _ W2 (Forall_nil _)) (Forall_cons _ _ _ W3 (Forall_nil _)))
      as (RH1 & RF1 & AC1 & RA1).
    assert (S01 : stack0 m1 lo shi).
    { eapply stack0_transport; [exact S0 | exact MU | exact WM | exact (Forall_cons _ _ _ W4 (Forall_nil _))]. }
    assert (EA : errno_addr tp + 4 <= 2 ^ 45).
    { rewrite TPV. apply Z.leb_le. vm_compute. reflexivity. }
    assert (ERR1 : rw_cells asegs m1 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR | exact MU | exact WM |]. cbn [disjoint_from cells_size csize]. split; [lia | exact I]. }
    assert (DSH : forall A n, 0 <= A -> 0 <= n -> A + n <= 2 ^ 47 -> disjoint_from [(spz - 96, spz)] (sh A) (nsh n)).
    { intros A n HA Hn HAn. pose proof (sh_nsh_high A n HA Hn ltac:(unfold AAPP_HI; lia)) as Hs.
      cbn [disjoint_from]. split; [|exact I]. unfold AHI_LO in Hs. lia. }
    assert (AD1' : addressable m1 o1 40).
    { eapply addressable_transport; [exact AD1 | exact MU | exact WM | apply DSH; lia]. }
    assert (AD2' : addressable m1 o2 40).
    { eapply addressable_transport; [exact AD2 | exact MU | exact WM | apply DSH; lia]. }
    assert (USH1 : umap_sh m1 24 (bl2, bc2, ents2)).
    { destruct USH as (US1 & US2). split.
      - intros Hb. change (bc2 <> 0) in Hb. change (addressable m1 bl2 (8 * bc2)).
        eapply addressable_transport; [exact (US1 Hb) | exact MU | exact WM |].
        apply DSH; [exact (UB3 Hb) | lia | exact (UB1 Hb)].
      - intros p k v Hi. change (In (p, (k, v)) ents2) in Hi.
        eapply addressable_transport; [exact (US2 p k v Hi) | exact MU | exact WM |].
        apply DSH; [exact (UB4 p k v Hi) | lia | exact (UB2 p k v Hi)]. }
    assert (XP1 : xpres H (LB0 ++ LBs2) spz XOB m0 m1).
    { eapply (xpres_munch_mixed H HH st0 LB (LB0 ++ LBs2) LBs1 spz XOB [(spz - 96, spz)] m0 m0 m1);
        [apply xpres_refl | exact RH | | lia | exact MU | exact WM | apply Forall_cons; [left; cbn [fst snd]; lia | apply Forall_nil]].
      eapply perm_trans; [exact PE|]. rewrite <- app_assoc. apply Permutation_app_head. apply Permutation_app_comm. }
    assert (OWN1 : lb_own LB m1) by exact (lb_own_wmono _ _ _ OWN WM).
    split.
    - unfold TS.
      exact (conj MI1 (conj ST1 (conj ERR1 (conj RA1 (conj AC1 (conj RF1 (conj S01 (conj RH1
               (conj FR (conj AD1' (conj AD2' (conj USH1 (conj XP1 OWN1))))))))))))).
    - eapply (apres_of_munch H HH st0 LB spz [(spz - 96, spz)] m0 m0 m1);
        [exact RH | exact MU | exact WM | apply Forall_cons; [cbn [fst snd]; lia | apply Forall_nil]].
  Qed.
  Lemma mva_entry : forall (bl1 bc1 bl2 bc2 : Z) (ents1 ents2 : list (Z * (Z * Z))) (LB LBs1 LBs2 : list block)
      (t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (msF : machine_state),
    as_VIS H st0 msF = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 o1) (Z_to_bv 64 o2) a2 a3 a4 a5 a6 a7
                              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 MVA) fc None m0 (seg_rom asegs) ->
    as_AKREL H st0 (mkCfg msF mo0) ->
    mem_inv asegs m0 -> stk asegs m0 lo spz -> rw_cells asegs m0 (errno_addr tp) [C4 errv] -> as_rauxv_ok H m0 B ->
    ACONST m0 -> as_RFS H LF m0 -> stack0 m0 lo shi -> as_RHEAP H st0 LB m0 -> lb_own LB m0 ->
    addressable m0 o1 40 -> addressable m0 o2 40 ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LB) m0 o1 bl1 bc1 ents1 -> umap_sh m0 24 (bl1, bc1, ents1) ->
    umapx MI_A 24 (nval24 ASEGS) (lbl LB) m0 o2 bl2 bc2 ents2 -> umap_sh m0 24 (bl2, bc2, ents2) ->
    Permutation LB (LB0 ++ LBs1 ++ LBs2) ->
    Permutation (lbl LBs1) (umap_blocks 24 bl1 bc1 ents1) -> Permutation (lbl LBs2) (umap_blocks 24 bl2 bc2 ents2) ->
    (forall b, In b LBs2 -> apart o1 40 (blk_addr b) (blk_size b)) ->
    as_SR H (mva_post bl2 bc2 ents2 LBs2) (mkCfg msF mo0).
Proof using All.
  intros bl1 bc1 bl2 bc2 ents1 ents2 LB LBs1 LBs2 t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F msF
    VIS KR MI ST ERR RA AC RF S0 RH OWN AD1 AD2 U1 SH1 U2 SH2 PE PM1 PM2 AP2.
  pose proof O1R as (O1a & O1b & O1c & O1d). pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
  pose proof SPZR as (SPa & SPb). pose proof LOH as (LOa & LOb). unfold AFREE_STACK in LOb.
  pose proof (aceil_facts) as ((ACF1 & ACF2) & ACF3 & ACF4).
  pose proof FS1 as (F1a & F1b).
  assert (O1T : AIMG_TOP <= o1) by exact O1a.
  assert (O2T : AIMG_TOP <= o2) by exact O2a.
  unfold AIMG_TOP in O1a, O2a.
  assert (U2' : umapx MI_A 24 (nval24 ASEGS) (lbl LBs2) m0 o2 bl2 bc2 ents2).
  { eapply ent_relive; [exact U2|]. intros p n Hi. exact (Permutation_in _ (Permutation_sym PM2) Hi). }
  destruct (hdr40_of_hdr m0 o1 bl1 bc1 ents1 (u_hdr U1) O1T ltac:(lia)) as (pad1 & HD1).
  destruct (hdr40_of_hdr m0 o2 bl2 bc2 ents2 (u_hdr U2) O2T ltac:(lia)) as (pad2 & HD2).
  destruct (ent_split LBs1 bl1 bc1 ents1 PM1) as (qb1 & LBn & PS & LN).
  assert (INn : forall b, In b LBn -> In b LB).
  { intros b Hb. apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. apply in_or_app. left.
    apply (Permutation_in _ (Permutation_sym PS)). apply in_or_app. right. exact Hb. }
  assert (INJ : bc1 <> 0 -> In (qb1, bl1, 8 * bc1) LB).
  { intros Hb. apply (Permutation_in _ (Permutation_sym PE)). apply in_or_app. right. apply in_or_app. left.
    apply (Permutation_in _ (Permutation_sym PS)). apply in_or_app. left.
    destruct (Z.eqb_spec bc1 0) as [E0|E0]; [contradiction | left; reflexivity]. }
  assert (B0 : bc1 = 0 -> bl1 = 0).
  { intros Hb. destruct (u_blive U1) as [[_ X]|[X _]]; [exact X | contradiction]. }
  assert (JK : exists junk1 : list byte, bc1 <> 0 -> rw_cells asegs m0 bl1 [CB (Z.to_nat (8 * bc1)) junk1]).
  { destruct (Z.eq_dec bc1 0) as [E0|E0]; [exists []; intros X; contradiction|].
    pose proof (ah_blocks H HH _ _ _ (qb1, bl1, 8 * bc1) RH (INJ E0)) as (Hq0 & Hq16 & Hqn & HqI & HqC & HqF & HqA).
    destruct (rw_cells_of_own LB m0 (qb1, bl1, 8 * bc1) OWN (INJ E0) HqI Hqn) as (bs & Hbs).
    exists bs. intros _. exact Hbs. }
  destruct JK as (junk1 & JK).
  assert (JB : forall m', apres H LB spz m0 m' -> bc1 <> 0 ->
            rw_cells asegs m' bl1 [CB (Z.to_nat (8 * bc1)) junk1] /\ addressable m' bl1 (8 * bc1)).
  { intros m' AP Hb.
    pose proof (ah_blocks H HH _ _ _ (qb1, bl1, 8 * bc1) RH (INJ Hb)) as (Hq0 & Hq16 & Hqn & HqI & HqC & HqF & HqA).
    unfold blk_addr, blk_size in Hqn. cbn [fst snd] in Hqn.
    split.
    - eapply (apres_rw_cells H); [exact AP | exact (JK Hb) |].
      eapply (aclient_range_block H); [exact (INJ Hb) | lia | cbn [cells_size csize]; rewrite Nat.add_0_r, Z2Nat.id by lia; lia].
    - eapply (apres_addressable H); [exact AP | exact (proj1 SH1 Hb) | exact (INJ Hb)]. }
  assert (HDT : forall m' bl bc fs sz mlf pad, apres H LB spz m0 m' ->
            hdr40 m0 o1 bl bc fs sz mlf pad -> hdr40 m' o1 bl bc fs sz mlf pad).
  { intros m' bl bc fs sz mlf pad AP HD. unfold hdr40 in *. eapply (apres_rw_cells H); [exact AP | exact HD |].
    unfold aclient_range. right; right; right; right; left. cbn [cells_size csize Nat.add]. lia. }
  assert (HDT2 : forall m' bl bc fs sz mlf pad, apres H LB spz m0 m' ->
            hdr40 m0 o2 bl bc fs sz mlf pad -> hdr40 m' o2 bl bc fs sz mlf pad).
  { intros m' bl bc fs sz mlf pad AP HD. unfold hdr40 in *. eapply (apres_rw_cells H); [exact AP | exact HD |].
    unfold aclient_range. cbn [cells_size csize Nat.add]. destruct FS2 as [F2|F2].
    - right; right; right; right; left. lia.
    - left. lia. }
  assert (GZ1 : gz m0 o1 40) by (intros i Hi; eapply sh0_of_addressable; [exact AD1 | change (8 * (40 / 8)) with 40; lia]).
  pose proof (ACONST_shbase m0 AC) as [CG CS].
  lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
  assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
  destruct (Z.eq_dec (Zlength ents1) 0) as [Z0|Z0].
  - assert (EN : ents1 = []).
    { destruct ents1 as [|e ents1]; [reflexivity|]. exfalso. unfold Zlength in Z0. cbn [length] in Z0. lia. }
    subst ents1.
    destruct LBn as [|bn LBn]; [|discriminate LN].
    pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 spz]).
    assert (HR : regs_ok E ent_sr R).
    { unfold ent_sr. apply regs_ok_srs; [apply regs_ok_seed|].
      repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
    assert (KG1 : kentry_ok asegs E m0 (KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL))).
    { eapply (kword_of_rw_cells asegs E m0 AGOT_SHBASE _ 0%nat (C8 (wz ASHBASE_CELL)));
        [exact CG | reflexivity | reflexivity | lia | reflexivity | unfold AGOT_SHBASE; lia | unfold AGOT_SHBASE; lia | reflexivity]. }
    assert (KG2 : kentry_ok asegs E m0 (KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit SHBASE))).
    { eapply (kword_of_rw_cells asegs E m0 ASHBASE_CELL _ 0%nat _);
        [exact CS | reflexivity | reflexivity | lia | reflexivity | unfold ASHBASE_CELL; lia | unfold ASHBASE_CELL; lia | reflexivity]. }
    assert (KW : kentry_ok asegs E m0 (KWr (SA (EVar 34) (-96)) (ELit 96))).
    { eapply kwr_of_stk; [exact ST | unfold estart; evs; rewrite u64_of_Z by lia; lia
                         | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
    assert (KZ : kentry_ok asegs E m0 (KWord (SA (EVar 32) 24) 8 (ELit 0))).
    { eapply (kword_of_rw_cells asegs E m0 o1 _ 24%nat (C8 (Z_to_bv 64 0)));
        [exact HD1 | reflexivity | reflexivity | lia
        | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off Z.of_nat]; lia | cbn; lia | cbn; lia | reflexivity]. }
    assert (HK : know_ok asegs E m0 (kn_fix 20 [MVA_L1] (SCR [] [] []) MVA ent_sr (ent_KN0 ++ [KWord (SA (EVar 32) 24) 8 (ELit 0)]) 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons; [exact KG1|]. apply Forall_cons; [exact KG2|]. apply Forall_cons; [exact KW|].
      apply Forall_cons; [exact KZ|]. know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA m0 (seg_rom asegs) HR HK 40%nat [MVA_L1] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m0 LG) in Hms; set (M1 := mem_denot E m0 LG) in Hms end.
    assert (LGc : LG = c8log (EVar 34) (-88) ent_tl) by reflexivity.
    assert (MU1 : munch [(spz - 96, spz)] m0 M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m0 M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (ST1 : stk asegs M1 lo spz) by (subst M1; apply stk_mem_denot; exact ST).
    assert (FR1 : mva_frame M1 (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9).
    { assert (CE : map (fun v => C8 (edenot E v)) ent_tl = [C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
        by (unfold E, ent_tl; subst R; reflexivity).
      unfold mva_frame. rewrite <- CE. subst M1. rewrite LGc. rewrite LGc in Hlf.
      apply rw_cells_c8log; [exact Hlf | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base]; lia |].
      change (8 * Z.of_nat (length ent_tl)) with 88.
      destruct ST as (STa & STb & STc).
      split; [lia|]. split; [lia|]. intros i Hi. exact (proj1 (STc (spz - 96 + 8 + i) ltac:(lia))). }
    destruct (ent_mem LB LBs1 LBs2 bl2 bc2 ents2 M1 MI ERR RA AC RF S0 RH OWN AD1 AD2 SH2 U2' PE MU1 WM1 MI1 ST1 FR1) as (TS1 & AP1).
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
    rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23.
    rewrite (w_addm spz (-96)) in G2 by lia. replace (spz + -96) with (spz - 96) in G2 by lia.
    rewrite G2, G8, G9, G18, G19, G20, G21, G22, G23 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply mva_t1 with (s := st0) (msF := msF1) (mo := mo1) (m := M1) (LB := LB) (LBs2 := LBs2) (qb1 := qb1) (junk1 := junk1)
                       (pad1 := pad1) (pad2 := pad2);
      [ exact VIS1 | exact KR1 | exact MP1 | exact TS1 | | lia | exact (HDT _ _ _ _ _ _ _ AP1 HD1) | exact (HDT2 _ _ _ _ _ _ _ AP1 HD2)
      | exact B0 | | exact U2' | exact PM2 | exact AP2 ].
    + eapply perm_trans; [exact PE|]. apply Permutation_app_head. apply Permutation_app_tail. rewrite app_nil_r in PS. exact PS.
    + intros Hb. destruct (JB M1 AP1 Hb) as (J1 & J2). pose proof (BSEQ_boundT bc1 (u_bseq U1)) as BQ.
      pose proof (u_bl_lo U1 Hb) as BL.
      split; [lia|]. split; [lia|]. split; [exact J1 | exact J2].
  - destruct ents1 as [|[p1 [k1 v1]] ents1]; [exfalso; apply Z0; reflexivity|].
    destruct (u_node U1 p1 k1 v1 (or_introl eq_refl)) as (_ & P1a & P1b & _).
    pose proof (u_load U1) as ULD. pose proof (BSEQ_boundT bc1 (u_bseq U1)) as BQ.
    remember (Zlength ((p1, (k1, v1)) :: ents1)) as zl eqn:EZL.
    assert (ZL : 0 < zl).
    { subst zl. unfold Zlength. cbn [length]. lia. }
    pose (E := Eseed R [Z_to_bv 64 o1; Z_to_bv 64 o2; Z_to_bv 64 spz; Z_to_bv 64 zl; Z_to_bv 64 p1]).
    assert (HR : regs_ok E ent_sr R).
    { unfold ent_sr. apply regs_ok_srs; [apply regs_ok_seed|].
      repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
    assert (KG1 : kentry_ok asegs E m0 (KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL))).
    { eapply (kword_of_rw_cells asegs E m0 AGOT_SHBASE _ 0%nat (C8 (wz ASHBASE_CELL)));
        [exact CG | reflexivity | reflexivity | lia | reflexivity | unfold AGOT_SHBASE; lia | unfold AGOT_SHBASE; lia | reflexivity]. }
    assert (KG2 : kentry_ok asegs E m0 (KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit SHBASE))).
    { eapply (kword_of_rw_cells asegs E m0 ASHBASE_CELL _ 0%nat _);
        [exact CS | reflexivity | reflexivity | lia | reflexivity | unfold ASHBASE_CELL; lia | unfold ASHBASE_CELL; lia | reflexivity]. }
    assert (KW : kentry_ok asegs E m0 (KWr (SA (EVar 34) (-96)) (ELit 96))).
    { eapply kwr_of_stk; [exact ST | unfold estart; evs; rewrite u64_of_Z by lia; lia
                         | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
    assert (KS : kentry_ok asegs E m0 (KWord (SA (EVar 32) 24) 8 (EVar 35))).
    { eapply (kword_of_rw_cells asegs E m0 o1 _ 24%nat (C8 (Z_to_bv 64 zl)));
        [exact HD1 | reflexivity | reflexivity | lia
        | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off Z.of_nat]; lia | cbn; lia | cbn; lia | reflexivity]. }
    assert (KF : kentry_ok asegs E m0 (KWord (SA (EVar 32) 16) 8 (EVar 36))).
    { eapply (kword_of_rw_cells asegs E m0 o1 _ 16%nat (C8 (Z_to_bv 64 p1)));
        [exact HD1 | reflexivity | reflexivity | lia
        | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off Z.of_nat]; lia | cbn; lia | cbn; lia | reflexivity]. }
    assert (HK : know_ok asegs E m0 (kn_fix 20 [MVA_LOOP] (SCR [false; false] [] []) MVA ent_sr
                   (ent_KN0 ++ [KWord (SA (EVar 32) 24) 8 (EVar 35); KWord (SA (EVar 32) 16) 8 (EVar 36)]) 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons; [exact KG1|]. apply Forall_cons; [exact KG2|]. apply Forall_cons; [exact KW|].
      apply Forall_cons; [exact KS|]. apply Forall_cons; [exact KF|]. know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R MVA m0 (seg_rom asegs) HR HK 40%nat [MVA_LOOP] (SCR [false; false] [] []) 40%N.
    { split_scs; try sc_auto1; try sc_shdj; try sc_dj. }
    lazymatch type of Hlf with log_flat _ ?lg => set (LG := lg) in Hlf end.
    lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m0 LG) in Hms; set (M1 := mem_denot E m0 LG) in Hms end.
    assert (LGc : LG = c8log (EVar 34) (-88) ent_tl) by reflexivity.
    assert (MU1 : munch [(spz - 96, spz)] m0 M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m0 M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (ST1 : stk asegs M1 lo spz) by (subst M1; apply stk_mem_denot; exact ST).
    assert (FR1 : mva_frame M1 (spz - 96) ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9).
    { assert (CE : map (fun v => C8 (edenot E v)) ent_tl = [C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
        by (unfold E, ent_tl; subst R; reflexivity).
      unfold mva_frame. rewrite <- CE. subst M1. rewrite LGc. rewrite LGc in Hlf.
      apply rw_cells_c8log; [exact Hlf | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base]; lia |].
      change (8 * Z.of_nat (length ent_tl)) with 88.
      destruct ST as (STa & STb & STc).
      split; [lia|]. split; [lia|]. intros i Hi. exact (proj1 (STc (spz - 96 + 8 + i) ltac:(lia))). }
    destruct (ent_mem LB LBs1 LBs2 bl2 bc2 ents2 M1 MI ERR RA AC RF S0 RH OWN AD1 AD2 SH2 U2' PE MU1 WM1 MI1 ST1 FR1) as (TS1 & AP1).
    assert (NODEF : forall p k v, In (p, (k, v)) ((p1, (k1, v1)) :: ents1) -> addressable m0 p 24 /\ AIMG_TOP <= p /\ p + 24 <= 2 ^ 47).
    { intros p k v Hi. split; [exact (proj2 SH1 p k v Hi)|]. split.
      - assert (Hl : In (p, 24) (lbl LBn)).
        { rewrite LN. apply in_map_iff. exists (p, (k, v)). split; [reflexivity | exact Hi]. }
        destruct (lbl_in_inv LBn p 24 Hl) as (id & Hid).
        pose proof (ah_blocks H HH _ _ _ (id, p, 24) RH (INn _ Hid)) as (_ & _ & _ & HpI & _).
        exact HpI.
      - destruct (u_node U1 p k v Hi) as (_ & _ & Hp & _). exact Hp. }
    destruct (nodes_exist ((p1, (k1, v1)) :: ents1) LBn m0 LN (u_chain U1) (lb_own_incl LB LBn m0 INn OWN) NODEF)
      as (ns & NOK0 & NF).
    pose proof (nodes_okA_apres LBn ns LB spz m0 M1 NOK0 AP1 INn) as NOK1.
    destruct ns as [|[q tl] ns]; [discriminate NF|].
    cbn [map fst] in NF. injection NF as Eq _. subst q.
    destruct LBn as [|b0 LBn]; [destruct NOK1|].
    readback HR' (msteps_full asegs _ _ Hms FHF) HR0 HRe.
    rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
    rreg HR' 20%bv G20. rreg HR' 21%bv G21. rreg HR' 22%bv G22. rreg HR' 23%bv G23. rreg HR' 24%bv G24.
    rewrite (w_addm spz (-96)) in G2 by lia. replace (spz + -96) with (spz - 96) in G2 by lia.
    rewrite G2, G8, G9, G10, G18, G19, G20, G21, G22, G23, G24 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1. rewrite HRe in VIS1. clear HRe.
    eapply (mva_loop ns p1 tl b0 LBn bl1 bc1 bl2 bc2 _ _ ents2 LB LBs2 qb1 junk1);
      [ exact VIS1 | exact KR1 | exact MP1 | exact TS1 | | lia | exact NOK1 | exact (HDT _ _ _ _ _ _ _ AP1 HD1)
      | exact (HDT2 _ _ _ _ _ _ _ AP1 HD2) | exact B0 | | exact U2' | exact PM2 | exact AP2 ].
    + eapply perm_trans; [exact PE|]. rewrite <- app_assoc. apply Permutation_app_head.
      change (b0 :: LBn ++ LBs2) with ((b0 :: LBn) ++ LBs2). rewrite app_assoc. apply Permutation_app_tail. exact PS.
    + intros Hb. destruct (JB M1 AP1 Hb) as (J1 & J2). pose proof (u_bl_lo U1 Hb) as BL.
      split; [lia|]. split; [lia|]. split; [exact J1 | exact J2].
Qed.

